using File=CodexKit.Native.NativeFile;
using Directory=CodexKit.Native.NativeDirectory;
using FileInfo=CodexKit.Native.NativeFileInfo;
using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Diagnostics;using System.Collections.Generic;
namespace CodexKit.Native {
public sealed class NativeUpdateManifest {public int schema_version;public string repository,component,version,url,sha256;}
public sealed class NativeUpdatePlan {public NativeUpdateManifest manifest;public string target,stage,originalHash;}
public sealed class NativeUpdater {
    public const string Repository="BerryFuwawa/codex-init-kit";
    public const string ManifestUrl="https://raw.githubusercontent.com/BerryFuwawa/codex-init-kit/main/native-update.json";
    readonly INativeDownloads downloads;
    public NativeUpdater(INativeDownloads source){downloads=source;}
    public static NativeUpdateManifest Parse(string text){var m=NativeData.Json.Deserialize<NativeUpdateManifest>(text);if(m==null||m.schema_version!=1||m.repository!=Repository||m.component!="native-init-cli"||!Regex.IsMatch(m.version??"",@"^\d+\.\d+\.\d+(?:\.\d+)?$")||!Regex.IsMatch(m.sha256??"",@"^[0-9a-f]{64}$"))throw new InvalidDataException("原生 CLI 更新清单格式、版本或组件不匹配；未使用旧 CMD 清单。");Uri uri;if(!Uri.TryCreate(m.url,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.Host!="github.com"||uri.UserInfo.Length>0||uri.Query.Length>0||uri.Fragment.Length>0||!uri.AbsolutePath.StartsWith("/"+Repository+"/releases/download/",StringComparison.Ordinal)||!uri.AbsolutePath.EndsWith("/CodexInitKit.Cli.exe",StringComparison.Ordinal))throw new InvalidDataException("原生 CLI 更新下载地址不属于本仓库。");return m;}
    public NativeUpdateManifest Check(){return Parse(downloads.Text(ManifestUrl,s=>{try{Parse(s);return true;}catch(ArgumentException){return false;}catch(InvalidDataException){return false;}}));}
    public NativeUpdatePlan Prepare(NativeUpdateManifest manifest,string target,string currentVersion){
        manifest=Parse(NativeData.Json.Serialize(manifest));if(new Version(manifest.version)<=new Version(currentVersion))throw new InvalidOperationException("当前原生 CLI 已是该通道的最新版本。");NativeData.NoLinks(target);if(!File.Exists(target))throw new FileNotFoundException("当前原生 CLI 文件不存在。",target);var plan=new NativeUpdatePlan{manifest=manifest,target=Path.GetFullPath(target),originalHash=NativeCua.Hash(target)};plan.stage=Path.Combine(Path.GetDirectoryName(plan.target),"CodexInitKit.Cli.next-"+Guid.NewGuid().ToString("N")+".exe");
        try{downloads.File(manifest.url,plan.stage,p=>ValidateCandidate(p,manifest));ValidateCandidate(plan.stage,manifest);if(NativeCua.Hash(target)!=plan.originalHash)throw new IOException("下载期间当前程序发生变化，未替换。");NativeData.Write(plan.stage+".json",NativeData.Json.Serialize(plan));return plan;}catch{if(File.Exists(plan.stage))File.Delete(plan.stage);if(File.Exists(plan.stage+".json"))File.Delete(plan.stage+".json");throw;}
    }
    public static void ValidateCandidate(string file,NativeUpdateManifest manifest){if(NativeCua.Hash(file)!=manifest.sha256)throw new InvalidDataException("原生 CLI 下载 SHA-256 不一致。");var version=FileVersionInfo.GetVersionInfo(NativePath.Io(file));if(version.ProductName!="Codex Init Kit Native CLI"||version.FileVersion!=manifest.version)throw new InvalidDataException("下载文件不是指定版本的原生 CLI 组件。");}
    public static string Apply(NativeUpdatePlan plan,Action<string> restart){
        Parse(NativeData.Json.Serialize(plan.manifest));NativeData.NoLinks(plan.target);NativeData.NoLinks(plan.stage);ValidateCandidate(plan.stage,plan.manifest);if(NativeCua.Hash(plan.target)!=plan.originalHash)throw new IOException("待更新目标已变化，停止替换。");if(!String.Equals(Path.GetDirectoryName(Path.GetFullPath(plan.target)),Path.GetDirectoryName(Path.GetFullPath(plan.stage)),StringComparison.OrdinalIgnoreCase)||String.Equals(plan.target,plan.stage,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("更新暂存与目标位置不匹配。");
        var backup=plan.target+".before-update-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8)+".bak";bool replaced=false;
        try{File.Replace(plan.stage,plan.target,backup);replaced=true;ValidateCandidate(plan.target,plan.manifest);restart(plan.target);return backup;}
        catch(Exception ex){if(replaced){try{if(NativeCua.Hash(plan.target)!=plan.manifest.sha256)throw new IOException("替换后目标又发生变化，保留两份文件供恢复。");var failed=plan.target+".failed-update-"+Guid.NewGuid().ToString("N")+".exe";File.Replace(backup,plan.target,failed);}catch(Exception rollback){throw new IOException("更新失败且未能自动恢复："+ex.Message+"；恢复："+rollback.Message+"；备份："+backup,rollback);}}throw new IOException("原生 CLI 更新未完成，原程序已保留或恢复："+ex.Message,ex);}
        finally{if(File.Exists(plan.stage))File.Delete(plan.stage);if(File.Exists(plan.stage+".json"))File.Delete(plan.stage+".json");}
    }
    public static string HelperPath(string cli){var path=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(cli)),"CodexInitKit.Updater.exe");if(!File.Exists(path)||FileVersionInfo.GetVersionInfo(NativePath.Io(path)).ProductName!="Codex Init Kit Native Updater")throw new FileNotFoundException("缺少匹配的原生更新组件，请使用完整的原生 CLI 文件包；未下载或替换程序。",path);return path;}
    public static int Complete(string planFile,int parentId,long parentStart){
        var plan=NativeData.Json.Deserialize<NativeUpdatePlan>(NativeData.Read(planFile));Process owner=null;try{owner=Process.GetProcessById(parentId);}catch(ArgumentException){}if(owner!=null)using(owner){if(!owner.HasExited){if(owner.StartTime.ToUniversalTime().Ticks!=parentStart)throw new InvalidOperationException("待退出进程身份发生变化，停止更新。");if(!owner.WaitForExit(30000))throw new TimeoutException("原 CLI 尚未退出，本次未替换。");}}
        try{var backup=Apply(plan,target=>{var info=new ProcessStartInfo(target,"--version"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(info)){if(process==null)throw new IOException("无法启动更新后的原生 CLI。");var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(10000)){process.Kill();process.WaitForExit();throw new TimeoutException("更新后的版本验证超时。");}if(!output.Wait(5000)||!error.Wait(5000)||process.ExitCode!=0||output.Result.IndexOf("Codex Init Kit Native CLI "+plan.manifest.version,StringComparison.Ordinal)<0)throw new IOException("更新后的原生 CLI 未返回期望版本。");}});NativeData.Write(plan.target+".update-result.json",NativeData.Json.Serialize(new{state="complete",version=plan.manifest.version,backup=backup}));Console.WriteLine("原生 CLI 已更新，请重新运行。旧程序保留于："+backup);return 0;}catch(Exception failure){NativeData.Write(plan.target+".update-result.json",NativeData.Json.Serialize(new{state="failed",error=failure.Message}));throw;}
    }
}
}
